import{_ as s,o as a,c as l,S as n}from"./chunks/framework.D1Ss-Xl7.js";const b=JSON.parse('{"title":"CSS笔记和杂谈","description":"这应该是最长的一次博客断更吧。。。因为年后辞职加上来日本工作的原因。导致很长时间都没有更新自己的博客了。很是惭愧，本来定的目标就是每月一篇很简单的任务。但居然空档了这么长时间，这就是正所谓的生于忧患死于安乐吧。找到了工作就松懈了，所以今天又…","frontmatter":{"title":"CSS笔记和杂谈","date":"2017-05-07 21:49","comments":true,"archives":2017,"tags":["css"]},"headers":[],"relativePath":"posts/2017-05-07-css/index.md","filePath":"posts/2017/2017-05-07-CSS.md"}'),o={name:"posts/2017-05-07-css/index.md"};function p(t,e,c,r,i,d){return a(),l("div",null,[...e[0]||(e[0]=[n(`<p>这应该是最长的一次博客断更吧。。。因为年后辞职加上来日本工作的原因。导致很长时间都没有更新自己的博客了。很是惭愧，本来定的目标就是每月一篇很简单的任务。但居然空档了这么长时间，这就是正所谓的生于忧患死于安乐吧。找到了工作就松懈了，所以今天又重新捡起来继续写。公司的新人课题是做一个简单的 CMS 网站，也算重新复习了一下网页制作吧，因为一直在写 JS 的项目，基本的 HTML 和 CSS 的设计都有点生疏了。。。</p><h2 id="css-一行多列设计" tabindex="-1">CSS 一行多列设计 <a class="header-anchor" href="#css-一行多列设计" aria-label="Permalink to &quot;CSS 一行多列设计&quot;">​</a></h2><p>这是一个最基本的设计布局。在一行上有多列的内容，最简单的例子是导航栏。HTML 的大致结构是这样的：</p><div class="language-html line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">&lt;</span><span style="color:#22863A;">ul</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#24292E;">  &lt;</span><span style="color:#22863A;">li</span><span style="color:#24292E;">&gt;HTML/CSS&lt;/</span><span style="color:#22863A;">li</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#24292E;">  &lt;</span><span style="color:#22863A;">li</span><span style="color:#24292E;">&gt;JavaScript&lt;/</span><span style="color:#22863A;">li</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#24292E;">  &lt;</span><span style="color:#22863A;">li</span><span style="color:#24292E;">&gt;CMS&lt;/</span><span style="color:#22863A;">li</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#24292E;">&lt;/</span><span style="color:#22863A;">ul</span><span style="color:#24292E;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>默认的话，这三列内容是向下排列的，如何让它们横着排列呢？这时候有三种解决方案：第一，是采用<code>float</code>使得所有的<code>li</code>列表浮动表示在一行。但这时候记得使用<code>clear</code>去清除浮动属性。这种设计方案的好处是兼容性强，但新手容易处理不好<code>float</code>属性对布局的影响和忘记清除<code>float</code>属性。第二种解决方案是对<code>li</code>使用<code>display:inline-block;</code>使得<code>li</code>并排一行，这种方案的好处是容易理解和兼容性高。但如果<code>li</code>之间的 HTML 源代码有回车的话会导致相邻的<code>li</code>有很细微的间距。所以对像素级别的设计方案来说并不推荐。第三种方案是使用<code>flex</code>布局。这是目前来说最灵活的一种布局方案了，特别对于多屏幕自适应来说非常友好。但是对浏览器版本要求比较高，IE11 以下都不支持。所以这个简单的布局方案要根据自己的业务情况进行具体选择，并没有银弹。</p><h2 id="子-div-溢出方案" tabindex="-1">子 DIV 溢出方案 <a class="header-anchor" href="#子-div-溢出方案" aria-label="Permalink to &quot;子 DIV 溢出方案&quot;">​</a></h2><p>有些时候根据需求我们设计的子 DIV 要比父 DIV 超出一定范围，这时候要怎么设计才好呢？有时候会想到利用<code>position: relative;</code>来改变子 DIV 的文档流进行实现。但这种方式实在是不推荐，因为会影响父 DIV 在页面的布局。我建议的解决方案是使用<code>margin</code>来进行溢出，<code>margin</code>不仅可以输入正数，也可以使用负数。当使用负数的时候就会朝反方向扩展达到溢出的目的。</p><h2 id="多行文字垂直居中" tabindex="-1">多行文字垂直居中 <a class="header-anchor" href="#多行文字垂直居中" aria-label="Permalink to &quot;多行文字垂直居中&quot;">​</a></h2><p>实际开发中，我们经常会遇到这种常见的需求，对于一行文字来说，很简单，我们只要把<code>height</code>和<code>line-height</code>设置成一样的高度就可以了。但是对于多行文字的话，我们还是需要一些技巧的。首先，我们需要在文字外面再套一层元素进行设置。HTML 结构大致是这样：</p><div class="language-html line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">&lt;</span><span style="color:#22863A;">div</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#24292E;">  &lt;</span><span style="color:#22863A;">span</span><span style="color:#24292E;">&gt;Lorem ipsum dolor sit amet, consectetur adipiscing elit.&lt;/</span><span style="color:#22863A;">span</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#24292E;">&lt;/</span><span style="color:#22863A;">div</span><span style="color:#24292E;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>然后我们在<code>div</code>上设置<code>height</code>和<code>line-height</code>一样高，使得<code>span</code>元素保持垂直居中。然后再修改<code>span</code>元素的 CSS 属性，设置正常的 line-height 和<code>display: inline-block;</code>以及<code>vertical-align: middle;</code>。</p><h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h2><p><a href="https://davidwalsh.name/remove-whitespace-inline-block" target="_blank" rel="noreferrer">remove-whitespace-inline-block</a></p><p><a href="https://developer.mozilla.org/en-US/docs/Web/CSS/display" target="_blank" rel="noreferrer">display</a></p><p><a href="https://codepen.io/CucuIonel/pen/espDH" target="_blank" rel="noreferrer">Vertical align multiple lines of text</a></p>`,15)])])}const m=s(o,[["render",p]]);export{b as __pageData,m as default};
